//! The provenance and completeness of a locally exported conversation.

use anyhow::{Context, ensure};
use link_model_contract::chat::media::{Part, Tokens};
use serde::{Deserialize, Serialize};

use super::{Evidence, Version};
use crate::runtime::Conversation;

/// A classification of updates generated by the local exporter. Imported
/// updates can contain arbitrary metadata and never create native records.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SessionEvidence {
    pub version: Version,
    pub conversation: Conversation,
    pub events: Vec<NativeEvent>,
    pub imported: Vec<UpdateRange>,
    pub read: ReadState,
}

impl SessionEvidence {
    /// Validates sequence identity and a complete, nonoverlapping
    /// classification of the session's portable updates.
    pub fn validate(&self, update_count: usize) -> anyhow::Result<()> {
        let count = u64::try_from(update_count).context("too many session updates")?;
        let mut last_seq = 0;
        for event in &self.events {
            ensure!(
                event.seq > last_seq,
                "native event {} is out of order",
                event.seq
            );
            last_seq = event.seq;
        }
        let mut ranges = self
            .events
            .iter()
            .map(|event| event.updates)
            .chain(self.imported.iter().copied())
            .collect::<Vec<_>>();
        for range in &ranges {
            ensure!(range.end()? <= count, "update range is outside the session");
        }
        ranges.retain(|range| range.len != 0);
        ranges.sort_by_key(|range| range.start);
        let mut next = 0;
        for range in ranges {
            ensure!(
                range.start == next,
                "overlapping or unclassified session updates"
            );
            next = range.end()?;
        }
        ensure!(next == count, "unclassified session updates");
        if let ReadState::Incomplete { gaps } = &self.read {
            ensure!(!gaps.is_empty(), "an incomplete snapshot names its gaps");
        }
        Ok(())
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct UpdateRange {
    pub start: u64,
    pub len: u64,
}

impl UpdateRange {
    fn end(self) -> anyhow::Result<u64> {
        self.start
            .checked_add(self.len)
            .context("session update range overflows")
    }
}

/// Allowlisted native metadata, retained even when the event has no
/// visible portable update. Thinking and unrestricted metadata stay out.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct NativeEvent {
    pub seq: u64,
    pub role: String,
    pub at: String,
    pub updates: UpdateRange,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub request: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub model: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub provider: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub response_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tokens: Option<Tokens>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub latency_ms: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cost: Option<f64>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub parts: Vec<Part>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub omissions: Vec<Omission>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub evidence: Option<Evidence>,
}

/// Export limitations remain separate from the stored snapshot's gaps.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "kebab-case", deny_unknown_fields)]
pub enum Omission {
    /// Internal media retains its part references, but ACP has no neutral
    /// internal-media update, so this export omits its bytes.
    InternalMedia,
}

/// Completeness of the retained store snapshot, not of tool execution.
/// A complete snapshot can still contain missing or unfinished evidence.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "kebab-case", deny_unknown_fields)]
pub enum ReadState {
    Complete,
    Incomplete { gaps: Vec<Gap> },
    Unknown { reason: String },
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "kebab-case", deny_unknown_fields)]
pub enum Gap {
    PartialLogTail { bytes: u64 },
    PartialCompactFrames { bytes: u64 },
    MissingPrefix { first_seq: u64 },
}

